  AND NOT EXISTS(SELECT 1 FROM merchant_payment_requests WHERE payment_id=NEW.id) THEN RAISE EXCEPTION 'A new merchant attempt requires its original provider request witness.' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $$;
